const pptxgen = require("pptxgenjs");
const fs = require("fs");
const path = require("path");

// ============================================================
// Color Palette: Midnight Executive (research-forward, technical)
// ============================================================
const C = {
  navy: "1E2761",
  iceBlue: "CADCFC",
  white: "FFFFFF",
  slate: "475569",
  lightGray: "F1F5F9",
  accentTeal: "0D9488",
  accentCoral: "F96167",
  accentGold: "F59E0B",
  darkText: "1E293B",
  mutedText: "64748B",
};

// ============================================================
// Helpers
// ============================================================
function freshShadow() {
  return { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.12 };
}

function makeSlideBg(pres, color, transparency) {
  return { color, transparency: transparency || 0 };
}

// ============================================================
// Presentation Setup
// ============================================================
let pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "KnowSelf Research";
pres.title = "KnowSelf: Teaching LLM Agents When to Think, Reflect, or Seek Knowledge";
pres.subject = "Agentic Knowledgeable Self-Awareness for LLM-Based Agents";

// ============================================================
// Slide 1: Title Slide
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = makeSlideBg(pres, C.navy);

  // Decorative accent bar on left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.12, h: 5.625,
    fill: { color: C.accentTeal },
  });

  // Top tag
  slide.addText("arXiv:2504.03553", {
    x: 0.5, y: 0.4, w: 9, h: 0.4,
    fontSize: 14, fontFace: "Calibri", color: C.iceBlue,
    align: "left", valign: "middle",
  });

  // Main title
  slide.addText("KnowSelf: Teaching LLM Agents When to Think, Reflect, or Seek Knowledge", {
    x: 0.5, y: 1.6, w: 9, h: 1.4,
    fontSize: 40, fontFace: "Georgia", color: C.white,
    bold: true, align: "left", valign: "top",
  });

  // Subtitle / tagline
  slide.addText("Agentic Knowledgeable Self-Awareness for LLM-Based Agents", {
    x: 0.5, y: 3.1, w: 9, h: 0.6,
    fontSize: 20, fontFace: "Calibri", color: C.iceBlue,
    align: "left", valign: "middle",
  });

  // Bottom line
  slide.addShape(pres.shapes.LINE, {
    x: 0.5, y: 4.6, w: 3, h: 0,
    line: { color: C.accentTeal, width: 2 },
  });

  slide.addText("Enabling agents to autonomously regulate knowledge utilization through situational self-awareness", {
    x: 0.5, y: 4.75, w: 9, h: 0.5,
    fontSize: 14, fontFace: "Calibri", color: C.white,
    align: "left", valign: "middle",
  });
}

// ============================================================
// Slide 2: Problem — Flood Irrigation
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = makeSlideBg(pres, C.white);

  // Title
  slide.addText("Current Agent Training Uses 'Flood Irrigation' — Indiscriminate Knowledge Injection Hurts Efficiency", {
    x: 0.5, y: 0.35, w: 9, h: 0.9,
    fontSize: 28, fontFace: "Georgia", color: C.navy,
    bold: true, align: "left", valign: "top",
  });

  // Three paradigm cards
  const cardY = 1.45;
  const cardH = 2.6;
  const cardW = 2.8;
  const gap = 0.3;
  const startX = 0.5;

  const paradigms = [
    {
      title: "Trajectory Imitation",
      example: "ReAct",
      desc: "Directly imitates gold trajectories without situational judgment.",
      color: C.accentCoral,
    },
    {
      title: "Trial-and-Error",
      example: "Reflexion",
      desc: "Injects external feedback indiscriminately across all steps.",
      color: C.accentGold,
    },
    {
      title: "Knowledge-Augmented",
      example: "KnowAgent, WKM",
      desc: "Floods every step with domain knowledge regardless of need.",
      color: C.accentTeal,
    },
  ];

  paradigms.forEach((p, i) => {
    let x = startX + i * (cardW + gap);
    // card bg
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: cardY, w: cardW, h: cardH,
      fill: { color: C.lightGray },
      shadow: freshShadow(),
    });
    // accent top bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: cardY, w: cardW, h: 0.08,
      fill: { color: p.color },
    });
    // title
    slide.addText(p.title, {
      x: x + 0.15, y: cardY + 0.2, w: cardW - 0.3, h: 0.4,
      fontSize: 16, fontFace: "Georgia", color: C.darkText,
      bold: true, align: "left", valign: "middle",
    });
    // example
    slide.addText(p.example, {
      x: x + 0.15, y: cardY + 0.6, w: cardW - 0.3, h: 0.3,
      fontSize: 13, fontFace: "Calibri", color: p.color,
      bold: true, align: "left", valign: "middle",
    });
    // desc
    slide.addText(p.desc, {
      x: x + 0.15, y: cardY + 0.95, w: cardW - 0.3, h: 1.4,
      fontSize: 13, fontFace: "Calibri", color: C.slate,
      align: "left", valign: "top",
    });
  });

  // Bottom insight box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.25, w: 9, h: 1.0,
    fill: { color: C.navy },
  });
  slide.addText("Humans possess situational self-awareness — the metacognitive ability to assess whether they can handle a situation directly, need to pause and reflect, or must seek external help. KnowSelf brings this capability to LLM agents.", {
    x: 0.7, y: 4.35, w: 8.6, h: 0.8,
    fontSize: 14, fontFace: "Calibri", color: C.white,
    align: "left", valign: "middle",
  });
}

// ============================================================
// Slide 3: Three Situational Modes (Decision Tree)
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = makeSlideBg(pres, C.white);

  // Title
  slide.addText("Three Situational Modes: Fast Thinking, Slow Thinking, and Knowledgeable Thinking", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 28, fontFace: "Georgia", color: C.navy,
    bold: true, align: "left", valign: "top",
  });

  // Decision tree layout
  const boxW = 2.6;
  const boxH = 1.1;
  const startY = 1.3;
  const level1Y = startY + boxH + 0.5;
  const level2Y = level1Y + boxH + 0.5;

  // Root: Decision Node
  slide.addShape(pres.shapes.RECTANGLE, {
    x: (10 - boxW) / 2, y: startY, w: boxW, h: boxH,
    fill: { color: C.navy },
    shadow: freshShadow(),
  });
  slide.addText("Agent Decision Step", {
    x: (10 - boxW) / 2, y: startY, w: boxW, h: boxH,
    fontSize: 16, fontFace: "Georgia", color: C.white,
    bold: true, align: "center", valign: "middle",
  });

  // Connector lines down
  slide.addShape(pres.shapes.LINE, {
    x: 5, y: startY + boxH, w: 0, h: 0.25,
    line: { color: C.slate, width: 1.5 },
  });
  slide.addShape(pres.shapes.LINE, {
    x: 2.2, y: startY + boxH + 0.25, w: 5.6, h: 0,
    line: { color: C.slate, width: 1.5 },
  });
  // vertical drops
  slide.addShape(pres.shapes.LINE, {
    x: 2.2, y: startY + boxH + 0.25, w: 0, h: 0.25,
    line: { color: C.slate, width: 1.5 },
  });
  slide.addShape(pres.shapes.LINE, {
    x: 5, y: startY + boxH + 0.25, w: 0, h: 0.25,
    line: { color: C.slate, width: 1.5 },
  });
  slide.addShape(pres.shapes.LINE, {
    x: 7.8, y: startY + boxH + 0.25, w: 0, h: 0.25,
    line: { color: C.slate, width: 1.5 },
  });

  // Level 1 criterion boxes
  const criteria = [
    { x: 0.9, text: "Predicted action matches gold action?", color: C.accentTeal },
    { x: 3.7, text: "Reflection fixes the action?", color: C.accentGold },
    { x: 6.5, text: "Still incorrect after reflection?", color: C.accentCoral },
  ];
  criteria.forEach((c) => {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: c.x, y: level1Y, w: boxW, h: boxH,
      fill: { color: C.lightGray },
      shadow: freshShadow(),
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: c.x, y: level1Y, w: boxW, h: 0.06,
      fill: { color: c.color },
    });
    slide.addText(c.text, {
      x: c.x + 0.1, y: level1Y + 0.1, w: boxW - 0.2, h: boxH - 0.2,
      fontSize: 13, fontFace: "Calibri", color: C.darkText,
      bold: true, align: "center", valign: "middle",
    });
  });

  // Connector lines down to modes
  [2.2, 5, 7.8].forEach((cx) => {
    slide.addShape(pres.shapes.LINE, {
      x: cx, y: level1Y + boxH, w: 0, h: 0.25,
      line: { color: C.slate, width: 1.5 },
    });
  });

  // Level 2: Mode boxes
  const modes = [
    {
      x: 0.9,
      title: "Fast Thinking",
      subtitle: "Direct correct action",
      desc: "Minimal deliberation. Agent acts immediately.",
      color: C.accentTeal,
    },
    {
      x: 3.7,
      title: "Slow Thinking",
      subtitle: "Self-correct via reflection",
      desc: "Agent pauses, reflects, then produces the right action.",
      color: C.accentGold,
    },
    {
      x: 6.5,
      title: "Knowledgeable Thinking",
      subtitle: "Consult external knowledge",
      desc: "Agent retrieves domain knowledge to resolve the step.",
      color: C.accentCoral,
    },
  ];

  modes.forEach((m) => {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: m.x, y: level2Y, w: boxW, h: 1.4,
      fill: { color: C.white },
      shadow: freshShadow(),
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: m.x, y: level2Y, w: boxW, h: 0.08,
      fill: { color: m.color },
    });
    slide.addText(m.title, {
      x: m.x + 0.1, y: level2Y + 0.15, w: boxW - 0.2, h: 0.35,
      fontSize: 15, fontFace: "Georgia", color: m.color,
      bold: true, align: "center", valign: "middle",
    });
    slide.addText(m.subtitle, {
      x: m.x + 0.1, y: level2Y + 0.5, w: boxW - 0.2, h: 0.25,
      fontSize: 12, fontFace: "Calibri", color: C.darkText,
      bold: true, align: "center", valign: "middle",
    });
    slide.addText(m.desc, {
      x: m.x + 0.1, y: level2Y + 0.75, w: boxW - 0.2, h: 0.55,
      fontSize: 11, fontFace: "Calibri", color: C.slate,
      align: "center", valign: "top",
    });
  });
}

// ============================================================
// Slide 4: KnowSelf Framework Pipeline
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = makeSlideBg(pres, C.white);

  // Title
  slide.addText("KnowSelf Framework: Data Construction → Two-Stage Training → Self-Aware Inference", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 28, fontFace: "Georgia", color: C.navy,
    bold: true, align: "left", valign: "top",
  });

  // Three pipeline stages as horizontal cards with arrows
  const stageW = 2.7;
  const stageH = 3.2;
  const stageY = 1.3;
  const startX = 0.45;
  const gap = 0.35;

  const stages = [
    {
      num: "1",
      title: "Self-Awareness Data Construction",
      body: "Agent self-explores environments. At each step, a heuristic criterion classifies the situation into fast, slow, or knowledgeable thinking. Special tokens are inserted to mark each situation type.",
      color: C.accentTeal,
    },
    {
      num: "2",
      title: "Two-Stage Training",
      body: "First, supervised fine-tuning (SFT) teaches the agent initial self-awareness patterns. Then, Reward-based Policy Optimization (RPO) further refines the agent's ability to generate appropriate special tokens.",
      color: C.accentGold,
    },
    {
      num: "3",
      title: "Self-Aware Inference",
      body: "During deployment, the agent generates special tokens that trigger either direct action, reflection, or knowledge retrieval from an external knowledge base.",
      color: C.accentCoral,
    },
  ];

  stages.forEach((s, i) => {
    let x = startX + i * (stageW + gap);
    // card
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: stageY, w: stageW, h: stageH,
      fill: { color: C.lightGray },
      shadow: freshShadow(),
    });
    // number circle
    slide.addShape(pres.shapes.OVAL, {
      x: x + 0.15, y: stageY + 0.15, w: 0.45, h: 0.45,
      fill: { color: s.color },
    });
    slide.addText(s.num, {
      x: x + 0.15, y: stageY + 0.15, w: 0.45, h: 0.45,
      fontSize: 16, fontFace: "Georgia", color: C.white,
      bold: true, align: "center", valign: "middle",
    });
    // title
    slide.addText(s.title, {
      x: x + 0.15, y: stageY + 0.7, w: stageW - 0.3, h: 0.6,
      fontSize: 15, fontFace: "Georgia", color: C.darkText,
      bold: true, align: "left", valign: "top",
    });
    // body
    slide.addText(s.body, {
      x: x + 0.15, y: stageY + 1.35, w: stageW - 0.3, h: 1.7,
      fontSize: 12, fontFace: "Calibri", color: C.slate,
      align: "left", valign: "top",
    });
  });

  // Arrows between stages
  for (let i = 0; i < 2; i++) {
    let arrowX = startX + (i + 1) * stageW + i * gap;
    let arrowY = stageY + stageH / 2 - 0.15;
    slide.addShape(pres.shapes.LINE, {
      x: arrowX, y: arrowY, w: gap, h: 0,
      line: { color: C.slate, width: 2 },
    });
    // arrow head (small triangle-ish via text)
    slide.addText("▶", {
      x: arrowX + gap - 0.12, y: arrowY - 0.14, w: 0.3, h: 0.3,
      fontSize: 14, color: C.slate,
      align: "center", valign: "middle",
    });
  }

  // Framework figure reference
  slide.addText("Framework reference: figure_3.jpg", {
    x: 0.5, y: 4.75, w: 9, h: 0.3,
    fontSize: 10, fontFace: "Calibri", color: C.mutedText,
    align: "right", valign: "middle",
  });
}

// ============================================================
// Slide 5: Qualitative Examples
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = makeSlideBg(pres, C.white);

  // Title
  slide.addText("KnowSelf Correctly Heats a Mug and Places a Saltshaker Where Baselines Fail", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 28, fontFace: "Georgia", color: C.navy,
    bold: true, align: "left", valign: "top",
  });

  // Two example cards side by side
  const cardW = 4.4;
  const cardH = 3.4;
  const cardY = 1.2;
  const leftX = 0.5;
  const rightX = 5.1;

  // Left card: Hot mug
  slide.addShape(pres.shapes.RECTANGLE, {
    x: leftX, y: cardY, w: cardW, h: cardH,
    fill: { color: C.lightGray },
    shadow: freshShadow(),
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: leftX, y: cardY, w: cardW, h: 0.08,
    fill: { color: C.accentCoral },
  });
  slide.addText("Task: Put a hot mug in cabinet", {
    x: leftX + 0.15, y: cardY + 0.15, w: cardW - 0.3, h: 0.4,
    fontSize: 15, fontFace: "Georgia", color: C.darkText,
    bold: true, align: "left", valign: "middle",
  });
  slide.addText([
    { text: "OpenAI-O1:", options: { bold: true, breakLine: true } },
    { text: "Incorrectly tries to take an egg from the microwave after opening it.", options: { breakLine: true } },
    { text: "", options: { breakLine: true } },
    { text: "KnowSelf (Llama-8B):", options: { bold: true, breakLine: true } },
    { text: "Uses a Reflection token to realize it should heat the mug using the open microwave.", options: {} },
  ], {
    x: leftX + 0.15, y: cardY + 0.6, w: cardW - 0.3, h: 2.5,
    fontSize: 13, fontFace: "Calibri", color: C.slate,
    align: "left", valign: "top",
  });

  // Right card: Saltshaker
  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: cardY, w: cardW, h: cardH,
    fill: { color: C.lightGray },
    shadow: freshShadow(),
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: cardY, w: cardW, h: 0.08,
    fill: { color: C.accentTeal },
  });
  slide.addText("Task: Put a saltshaker in drawer", {
    x: rightX + 0.15, y: cardY + 0.15, w: cardW - 0.3, h: 0.4,
    fontSize: 15, fontFace: "Georgia", color: C.darkText,
    bold: true, align: "left", valign: "middle",
  });
  slide.addText([
    { text: "DeepSeek-R1:", options: { bold: true, breakLine: true } },
    { text: "Reflects that the drawer is open and tries to close it first (which fails).", options: { breakLine: true } },
    { text: "", options: { breakLine: true } },
    { text: "KnowSelf:", options: { bold: true, breakLine: true } },
    { text: "Applies a Knowledge token noting that the agent should place the object without removing unrelated items.", options: {} },
  ], {
    x: rightX + 0.15, y: cardY + 0.6, w: cardW - 0.3, h: 2.5,
    fontSize: 13, fontFace: "Calibri", color: C.slate,
    align: "left", valign: "top",
  });

  // Figure reference
  slide.addText("Qualitative comparison reference: figure_1.jpg", {
    x: 0.5, y: 4.75, w: 9, h: 0.3,
    fontSize: 10, fontFace: "Calibri", color: C.mutedText,
    align: "right", valign: "middle",
  });
}

// ============================================================
// Slide 6: ALFWorld Results Table
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = makeSlideBg(pres, C.white);

  // Title
  slide.addText("KnowSelf Achieves 84.33% on ALFWorld with Llama-8B Using Only 15% Knowledge", {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 26, fontFace: "Georgia", color: C.navy,
    bold: true, align: "left", valign: "top",
  });

  // Table data
  const headers = [
    { text: "Backbone", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "center" } },
    { text: "Method", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "center" } },
    { text: "Know%", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "center" } },
    { text: "Put", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "center" } },
    { text: "Clean", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "center" } },
    { text: "Heat", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "center" } },
    { text: "Cool", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "center" } },
    { text: "Examine", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "center" } },
    { text: "Put Two", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "center" } },
    { text: "All", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "center" } },
  ];

  const rows = [
    ["GPT-4o", "ReAct", "0%", "83.33", "74.19", "69.57", "85.71", "77.78", "64.71", "76.12"],
    ["GPT-4o", "Reflexion", "0%", "100.00", "87.10", "73.91", "90.48", "83.33", "70.59", "85.07"],
    ["GPT-4o", "ExpeL", "100%", "95.83", "83.87", "69.57", "80.95", "88.89", "52.94", "79.85"],
    ["Llama-8B", "ReAct", "0%", "33.33", "3.23", "0.00", "57.14", "66.67", "23.53", "27.61"],
    ["Llama-8B", "Reflexion", "0%", "62.96", "22.73", "5.88", "64.29", "86.36", "50.00", "51.49"],
    ["Llama-8B", "ExpeL", "100%", "83.33", "32.26", "30.43", "23.81", "55.56", "17.65", "41.04"],
    ["Llama-8B", "ETO", "0%", "91.67", "70.59", "82.61", "61.90", "88.89", "64.71", "78.36"],
    ["Llama-8B", "KnowAgent", "100%", "87.50", "93.55", "65.22", "66.67", "61.11", "64.71", "75.37"],
    ["Llama-8B", "WKM", "100%", "95.83", "87.10", "86.96", "61.90", "66.67", "52.94", "77.61"],
    ["Llama-8B", "KnowSelf", "15.01%", "91.67", "87.10", "91.30", "85.71", "77.78", "64.71", "84.33"],
    ["Gemma-2B", "ReAct", "0%", "0.00", "9.68", "0.00", "4.76", "44.44", "0.00", "8.96"],
    ["Gemma-2B", "ETO", "0%", "91.67", "83.87", "78.26", "52.38", "77.78", "29.41", "71.64"],
    ["Gemma-2B", "KnowAgent", "100%", "91.67", "90.32", "69.57", "71.43", "66.67", "41.18", "73.88"],
    ["Gemma-2B", "WKM", "100%", "91.67", "87.10", "78.26", "71.43", "61.11", "52.94", "76.12"],
    ["Gemma-2B", "KnowSelf", "26.41%", "87.50", "93.55", "73.91", "76.19", "83.33", "52.94", "79.85"],
  ];

  function makeRow(cells, isHighlight) {
    return cells.map((text, idx) => {
      let base = { text, options: { align: "center", fontFace: "Calibri", fontSize: 9 } };
      if (isHighlight) {
        base.options.bold = true;
        base.options.fill = { color: "E0F2FE" }; // light ice blue
        base.options.color = C.navy;
      } else {
        base.options.color = C.darkText;
      }
      // Know% column styling
      if (idx === 2) {
        if (text === "100%") base.options.color = C.accentCoral;
        if (text === "15.01%" || text === "26.41%") base.options.color = C.accentTeal;
        if (isHighlight) base.options.color = C.navy;
      }
      return base;
    });
  }

  let tableData = [headers];
  rows.forEach((r, i) => {
    const isHighlight = (i === 9 || i === 14); // KnowSelf rows
    tableData.push(makeRow(r, isHighlight));
  });

  slide.addTable(tableData, {
    x: 0.3, y: 1.1, w: 9.4, h: 3.6,
    border: { pt: 0.5, color: "CBD5E1" },
    colW: [1.1, 1.2, 0.8, 0.75, 0.75, 0.75, 0.75, 0.85, 0.85, 0.75],
    fontFace: "Calibri",
