const pptxgen = require("pptxgenjs");

// ============================================================
// Color Palette: Midnight Executive (research-forward, technical)
// ============================================================
const C = {
  navy: "1E2761",
  iceBlue: "CADCFC",
  white: "FFFFFF",
  slate: "475569",
  lightGray: "F1F5F9",
  accentTeal: "0D9488",
  accentCoral: "F96167",
  accentGold: "F59E0B",
  darkText: "1E293B",
  mutedText: "64748B",
};

function freshShadow() {
  return { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.12 };
}

// ============================================================
// Presentation Setup
// ============================================================
let pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "KnowSelf Research";
pres.title = "KnowSelf: Teaching LLM Agents When to Think, Reflect, or Seek Knowledge";
pres.subject = "Agentic Knowledgeable Self-Awareness for LLM-Based Agents";

// ============================================================
// Slide 1: Title Slide
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.navy };

  // Top tag
  slide.addText("arXiv:2504.03553", {
    x: 0.5, y: 0.4, w: 9, h: 0.4,
    fontSize: 14, fontFace: "Calibri", color: C.iceBlue,
    align: "left", valign: "middle",
  });

  // Main title
  slide.addText("KnowSelf: Teaching LLM Agents When to Think, Reflect, or Seek Knowledge", {
    x: 0.5, y: 1.6, w: 9, h: 1.4,
    fontSize: 40, fontFace: "Georgia", color: C.white,
    bold: true, align: "left", valign: "top",
  });

  // Subtitle / tagline
  slide.addText("Agentic Knowledgeable Self-Awareness for LLM-Based Agents", {
    x: 0.5, y: 3.1, w: 9, h: 0.6,
    fontSize: 20, fontFace: "Calibri", color: C.iceBlue,
    align: "left", valign: "middle",
  });

  // Bottom line
  slide.addShape(pres.shapes.LINE, {
    x: 0.5, y: 4.6, w: 3, h: 0,
    line: { color: C.accentTeal, width: 2 },
  });

  slide.addText("Enabling agents to autonomously regulate knowledge utilization through situational self-awareness", {
    x: 0.5, y: 4.75, w: 9, h: 0.5,
    fontSize: 14, fontFace: "Calibri", color: C.white,
    align: "left", valign: "middle",
  });
}

// ============================================================
// Slide 2: Problem — Flood Irrigation
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.white };

  // Title
  slide.addText("Current Agent Training Uses 'Flood Irrigation' — Indiscriminate Knowledge Injection Hurts Efficiency", {
    x: 0.5, y: 0.35, w: 9, h: 0.9,
    fontSize: 28, fontFace: "Georgia", color: C.navy,
    bold: true, align: "left", valign: "top",
  });

  // Three paradigm cards
  const cardY = 1.45;
  const cardH = 2.3;
  const cardW = 2.8;
  const gap = 0.3;
  const startX = 0.5;

  const paradigms = [
    {
      title: "Trajectory Imitation",
      example: "ReAct",
      desc: "Directly imitates gold trajectories without situational judgment.",
      color: C.accentCoral,
    },
    {
      title: "Trial-and-Error",
      example: "Reflexion",
      desc: "Injects external feedback indiscriminately across all steps.",
      color: C.accentGold,
    },
    {
      title: "Knowledge-Augmented",
      example: "KnowAgent, WKM",
      desc: "Floods every step with domain knowledge regardless of need.",
      color: C.accentTeal,
    },
  ];

  paradigms.forEach((p, i) => {
    let x = startX + i * (cardW + gap);
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: cardY, w: cardW, h: cardH,
      fill: { color: C.lightGray },
